const maxint = Number.MAX_SAFE_INTEGER / 10000;

class LSystem {
    constructor() {
        this.angle = 20;
        this.segmentLength = 40;
        this.decrease = 0.7;
        this.threshold = 3.0;
        this.rules = {
            '1': 'FFF[++2][+2][-2][--2]',
            '2': 'FFF[++3][+3][-4][--4]',
            '3': 'FFF[++5][+5][-5][--5]',
            '4': 'FFF[++5][+5][-5][--5]',
            '5': 'FFFFF[++5][--5]'
        };
        this.premise = '1';
        this._timed = false;
        this.cost = 0.25;
        this.shape = g.rect(0, 0, 100, 100);
        this.scale = 1;
        this.time = null;
        this.ease = null;
        this.outputAsData = false;
        this.reset();
    }

    reset() {
        this._segments = 0;
        this._duration = 0;
        this._transform = g.Transform.IDENTITY;
        this._transformStack = [];
        this._shapes = [];
        this._data = [];
    }

    _grow(generation, rule, angle, length, time = maxint, draw = true) {
        if (generation === 0) {
            this._duration = 1 + maxint - time
        }

        if (length <= this.threshold) {
            this._duration = 1 + maxint - time
            return;
        }

        if (draw) {
            let transform = this._transform;
            if (rule === 'f') {
                this._transform = transform.translate(0, -Math.min(length, length * time));
            } else if (rule === '-') {
                this._transform = transform.rotate(Math.max(-angle, -angle * time));
            } else if (rule === '+') {
                this._transform = transform.rotate(Math.min(angle, angle * time));
            } else if (rule === '|') {
                this._transform = transform.rotate(180);
            } else if (rule === '[') {
                this._transformStack.push(this._transform);
            } else if (rule === ']') {
                this._transform = this._transformStack.pop();
            }
        }

        if (this.rules[rule] !== undefined && generation > 0 && time > 0) {
            for (let i = 0; i < this.rules[rule].length; i += 1) {
                let cmd = this.rules[rule][i];
                if (cmd === 'F') {
                    time -= this.cost;
                } else if (cmd === '!') {
                    angle = -angle;
                } else if (cmd === '(') {
                    angle *= 1.1;
                } else if (cmd === ')') {
                    angle *= 0.9;
                } else if (cmd === '<') {
                    length *= 0.9;
                } else if (cmd === '>') {
                    length *= 1.1;
                }
                this._grow(generation - 1, cmd, angle, length * this.decrease, time, draw);
            }
        } else if (rule === 'F' || (this.rules[rule] === '')) {
            this._segments += 1;
            if (draw && time >= 0) {
                length = Math.min(length, length * time);
                if (this._timed) {
                    this.segment(length, generation, time, this._segments);
                } else {
                    this.segment(length, generation, null, this._segments);
                }
                let transform = this._transform;
                this._transform = transform.translate(0, -length);
            }
        }
    }

    segment(length, generation, time = null, id = null) {
        let transform = this._transform;
        if (this.scale !== 1) {
            transform = transform.scale(this.scale);
        }
        if (this.outputAsData) {
            this._data.push({
                generation,
                length,
                rel_length: length / this.segmentLength,
                time,
                id,
                transform
            });
        } else {
            const height = g.bounds(this.shape).height;
            transform = transform.scale(length / height);
            const shape = transform.transformShape(this.shape);
            this._shapes.push(shape);
        }
    }

    draw(x, y, generation) {
        let angle = this.angle;
        if (this.time && this.ease) {
            angle = Math.min(this.angle, this.angle * this.time / this.ease);
        }
        this._timed = true;
        let time = this.time;
        if (!time) {
            this._timed = false;
            time = maxint;
        }
        this._transform = this._transform.translate(x, y);
        for (let i = 0; i < this.premise.length; i += 1) {
            let cmd = this.premise[i];
            this._grow(generation, cmd, angle, this.segmentLength, time, true);
        }
    }
}

lsystem.LSystem = LSystem;
lsystem.maxint = maxint;

lsystem.lsystem = function (rules, premise, angle, segmentLength, decrease, threshold, cost) {
    const lines = rules.split('\n');
    rules = {};
    lines.forEach(l => {
        if (l.length === 0) {
            return;
        }
        let m = l.split(':');
        if (m.length !== 2) {
            throw new Error('Invalid rule: ' + l);
        }
        let name = m[0].trim();
        if (rules[name] !== undefined) {
            throw new Error('Rule ' + name + ' already exists.');
        }
        rules[name] = m[1].trim();
    });
    return {
        rules,
        premise,
        angle,
        segmentLength,
        decrease,
        threshold,
        cost
    };
};

lsystem.createLSystem = function (lsystemData, shape, scale, time, ease) {
    const ls = new lsystem.LSystem();
    Object.keys(lsystemData).forEach(k => { ls[k] = lsystemData[k]; });
    if (shape) {
        ls.shape = shape;
    }
    ls.scale = scale;
    ls.time = time <= 0 ? lsystem.maxint : time;
    ls.ease = ease > 0 ? ease : null;
    return ls;
};

lsystem.lsystemDraw = function (lsystemData, shape, position, scale, generations, time, ease) {
    const ls = lsystem.createLSystem(lsystemData, shape, scale, time, ease);
    ls.draw(position.x, position.y, generations);
    return ls._shapes;
};

lsystem.lsystemData = function (lsystemData, position, generations, time, ease) {
    const ls = lsystem.createLSystem(lsystemData, null, 1, time, ease);
    ls.outputAsData = true;
    ls.draw(position.x, position.y, generations);
    return ls._data;
};
